import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ContentService, Biography, TimelineItem } from '@core/services/content.service';

@Component({
  selector: 'app-biografia',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './biografia.component.html',
  styleUrl: './biografia.component.scss',
})
export class BiografiaComponent implements OnInit {
  timelineItems: TimelineItem[] = [];
  portraitUrl = '';
  stats: any[] = [];

  constructor(private contentService: ContentService) {}

  ngOnInit() {
    this.contentService.getBiography().subscribe({
      next: (bio: Biography) => {
        this.portraitUrl = bio.portraitUrl;
        this.timelineItems = bio.timelineItems;
        this.stats = bio.stats;
      },
      error: (err: any) => console.error('Error loading biography:', err),
    });
  }

  // Fallback data
  fallbackTimelineItems = [
    { year: '1965', title: 'Nascita', description: 'Pualin Zefi nasce a Lezha' },
    { year: '1989', title: 'Laurea', description: 'Si laurea in Storia Medievale all\'Università di Tirana' },
    { year: '1995', title: 'Primi Studi', description: 'Pubblica i primi studi sui manoscritti della Lega di Alessio' },
    { year: '2005', title: 'Conservatore', description: 'Diventa Conservatore del Patrimonio Storico di Lezha' },
    { year: '2015', title: 'Riconoscimento', description: 'Riceve il riconoscimento internazionale per i suoi studi' },
    { year: '2024', title: 'Custode della Memoria', description: 'Dirige il progetto di conservazione digitale della memoria albanese' }
  ];
}
<section id="biografia" class="biografia-section">
  <div class="section-header">
    <span class="section-tag">Capitolo I</span>
    <h2 class="section-title">La Vita di uno Storico</h2>
    <p class="section-subtitle">Quarant'anni di ricerca, passione e dedizione alla memoria</p>
  </div>

  <div class="biografia-content">
    <div class="biografia-portrait">
      <div class="portrait-frame">
        <img src="https://via.placeholder.com/400x500" alt="Pualin Zefi">
        <div class="portrait-corner portrait-corner-tl"></div>
        <div class="portrait-corner portrait-corner-tr"></div>
        <div class="portrait-corner portrait-corner-bl"></div>
        <div class="portrait-corner portrait-corner-br"></div>
      </div>
      <blockquote class="portrait-quote">«La storia non è il passato, è la chiave del futuro.»</blockquote>
    </div>

    <div class="biografia-text">
      <h3>Pualin Zefi</h3>
      <p class="role">Storico, Ricercatore, Conservatore del Patrimonio Albanese</p>

      <p>Con più di quarant'anni dedicati alla ricerca storica, Pualin Zefi è divenuto una figura di riferimento nello studio della storia medievale albanese e, in particolare, della città di Lezha. La sua dedizione ha permesso di far luce su periodi oscuri della storia albanese.</p>

      <p>Attraverso archivi europei, manoscritti inediti e testimonianze orali, ha ricostruito la complessità degli eventi che hanno segnato l'Impero Ottomano e la resistenza albanese.</p>

      <p>La sua missione è semplice ma profonda: preservare la memoria di Lezha e trasmetterla alle generazioni future, affinché non si dimentichino i sacrifici e la gloria di coloro che hanno difeso questa terra.</p>

      <div class="stats">
        <div class="stat">
          <span class="stat-number">40+</span>
          <span class="stat-label">Anni di Ricerca</span>
        </div>
        <div class="stat">
          <span class="stat-number">15</span>
          <span class="stat-label">Pubblicazioni</span>
        </div>
        <div class="stat">
          <span class="stat-number">200+</span>
          <span class="stat-label">Conferenze</span>
        </div>
      </div>
    </div>
  </div>

  <div class="timeline">
    <div class="timeline-item" *ngFor="let item of timelineItems">
      <div class="timeline-dot"></div>
      <div class="timeline-content" [attr.data-year]="item.year">
        <h4>{{ item.title }}</h4>
        <p>{{ item.description }}</p>
      </div>
    </div>
  </div>
</section>
